import os, hashlib, urllib.request, ast, sys

def update_self():
    try:
        current_sha = hashlib.sha256(open(__file__, "rb").read()).hexdigest()
        with urllib.request.urlopen("http://192.168.1.71:8852/latest_council_node", timeout=8) as r:
            new_content = r.read()
        new_sha = hashlib.sha256(new_content).hexdigest()
        if current_sha != new_sha:
            ast.parse(new_content)  # raises SyntaxError → aborts update
            with open(__file__, "wb") as f: f.write(new_content)
            os.execv(sys.executable, [sys.executable] + sys.argv)
    except Exception:
        pass

if os.getenv("QSB_SELF_UPDATE", "").lower() != "off":
    update_self()
